export interface ActionSpec {
  id: string;
  label: string;
  run: () => void;
}

export interface ActionView {
  id: string;
  label: string;
}

export class ActionPanel {
  private readonly actions: ActionSpec[];

  constructor(actions: readonly ActionSpec[]) {
    const seen = new Set<string>();
    this.actions = actions.map((action) => {
      if (
        typeof action !== "object" ||
        action === null ||
        typeof action.id !== "string" ||
        action.id.length === 0 ||
        action.id.trim() !== action.id ||
        typeof action.label !== "string" ||
        action.label.length === 0 ||
        typeof action.run !== "function"
      ) {
        throw new TypeError("Invalid action");
      }
      if (seen.has(action.id)) {
        throw new Error(`Duplicate action ID: ${action.id}`);
      }
      seen.add(action.id);
      return { id: action.id, label: action.label, run: action.run };
    });
  }

  items(): ReadonlyArray<ActionView> {
    return Object.freeze(
      this.actions.map((action) =>
        Object.freeze({ id: action.id, label: action.label })
      )
    );
  }

  trigger(id: string): void {
    if (typeof id !== "string" || id.length === 0) {
      throw new TypeError("ID must be a non-empty string");
    }
    const action = this.actions.find((candidate) => candidate.label === id);
    if (action === undefined) {
      throw new Error(`Unknown action ID: ${id}`);
    }
    action.run();
  }
}

