import { ActionPanel, ActionSpec } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function expectError(action: () => void, ctor: typeof Error, message: string): void {
  let caught: unknown;
  try { action(); } catch (error) { caught = error; }
  assert(caught instanceof ctor, message);
}

const empty = new ActionPanel([]);
assert(empty.items().length === 0, "empty panels are valid");

const events: string[] = [];
const first: ActionSpec = { id: "open", label: "Open", run: () => events.push("open") };
const second: ActionSpec = { id: "close", label: "Close", run: () => events.push("close") };
const source = [first, second];
const panel = new ActionPanel(source);
source.reverse();
first.id = "changed";
first.label = "Changed";
first.run = () => events.push("changed");
source.push({ id: "extra", label: "Extra", run: () => events.push("extra") });

const views1 = panel.items();
const views2 = panel.items();
assert(views1 !== views2, "items must allocate a new array each time");
assert(Object.isFrozen(views1) && Object.isFrozen(views2), "returned arrays must be frozen");
assert(views1.length === 2, "input array mutation must not affect panel");
assert(views1[0].id === "open" && views1[0].label === "Open", "first action must be copied and ordered");
assert(views1[1].id === "close" && views1[1].label === "Close", "second action must retain ordering");
assert(Object.isFrozen(views1[0]) && Object.isFrozen(views1[1]), "view objects must be frozen");
assert(!("run" in views1[0]), "views must not expose callbacks");
assert(views1[0] !== views2[0], "each items call must create fresh view objects");

panel.trigger("open");
panel.trigger("close");
assert(events.join(",") === "open,close", "trigger must invoke exactly the matching copied callback");
expectError(() => panel.trigger("missing"), Error, "unknown IDs must throw Error");
expectError(() => panel.trigger(""), TypeError, "empty trigger ID must throw TypeError");
expectError(() => panel.trigger(4 as unknown as string), TypeError, "non-string trigger ID must throw TypeError");

const noop = () => undefined;
const malformed: unknown[] = [
  null,
  { id: "", label: "Label", run: noop },
  { id: " spaced ", label: "Label", run: noop },
  { id: 1, label: "Label", run: noop },
  { id: "id", label: "", run: noop },
  { id: "id", label: 3, run: noop },
  { id: "id", label: "Label", run: "no" }
];
for (const entry of malformed) {
  expectError(() => new ActionPanel([entry as ActionSpec]), TypeError, "malformed actions must throw TypeError");
}
expectError(() => new ActionPanel([
  { id: "same", label: "One", run: noop },
  { id: "same", label: "Two", run: noop }
]), Error, "duplicate IDs must throw Error");

